ALTER TABLE public.assessment_invitations ADD COLUMN IF NOT EXISTS token_hash text;
UPDATE public.assessment_invitations SET token_hash = encode(extensions.digest(convert_to(token, 'UTF8'), 'sha256'), 'hex') WHERE token_hash IS NULL AND token IS NOT NULL;
ALTER TABLE public.assessment_invitations ALTER COLUMN token DROP NOT NULL, ALTER COLUMN token_hash SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_assessment_invitations_token_hash ON public.assessment_invitations(token_hash);
ALTER TABLE public.assessment_responses ADD COLUMN IF NOT EXISTS submission_batch_id uuid, ADD COLUMN IF NOT EXISTS establishment_id uuid REFERENCES public.establishments(id), ADD COLUMN IF NOT EXISTS department_id uuid REFERENCES public.departments(id);
WITH batches AS (SELECT invitation_id, gen_random_uuid() AS batch_id FROM public.assessment_responses WHERE submission_batch_id IS NULL GROUP BY invitation_id) UPDATE public.assessment_responses ar SET submission_batch_id = b.batch_id, establishment_id = ai.establishment_id, department_id = ai.department_id FROM batches b JOIN public.assessment_invitations ai ON ai.id = b.invitation_id WHERE ar.invitation_id = b.invitation_id;
ALTER TABLE public.assessment_responses ALTER COLUMN submission_batch_id SET NOT NULL, ALTER COLUMN invitation_id DROP NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS idx_assessment_responses_batch_item ON public.assessment_responses(submission_batch_id, item_id);
CREATE INDEX IF NOT EXISTS idx_assessment_responses_cycle_group ON public.assessment_responses(cycle_id, establishment_id, department_id);
CREATE TABLE IF NOT EXISTS public.assessment_dispatches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES public.organizations(id), cycle_id uuid NOT NULL REFERENCES public.assessment_cycles(id), employee_id uuid NOT NULL REFERENCES public.employee_profiles(id), establishment_id uuid REFERENCES public.establishments(id), department_id uuid REFERENCES public.departments(id), channel text NOT NULL CHECK (channel IN ('email','whatsapp')), status text NOT NULL CHECK (status IN ('sent','failed')), provider_id text, error_code text, created_by uuid REFERENCES auth.users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (cycle_id, employee_id));
ALTER TABLE public.assessment_dispatches ENABLE ROW LEVEL SECURITY;
CREATE POLICY assessment_dispatches_select_admin ON public.assessment_dispatches FOR SELECT TO authenticated USING (tenant_id = public.fn_resolve_tenant_id() AND public.fn_user_has_role(ARRAY['owner'::public.organization_role,'admin'::public.organization_role,'manager'::public.organization_role]));
CREATE POLICY assessment_dispatches_insert_admin ON public.assessment_dispatches FOR INSERT TO authenticated WITH CHECK (tenant_id = public.fn_resolve_tenant_id() AND public.fn_user_has_role(ARRAY['owner'::public.organization_role,'admin'::public.organization_role,'manager'::public.organization_role]));
CREATE POLICY assessment_dispatches_update_admin ON public.assessment_dispatches FOR UPDATE TO authenticated USING (tenant_id = public.fn_resolve_tenant_id() AND public.fn_user_has_role(ARRAY['owner'::public.organization_role,'admin'::public.organization_role,'manager'::public.organization_role])) WITH CHECK (tenant_id = public.fn_resolve_tenant_id() AND public.fn_user_has_role(ARRAY['owner'::public.organization_role,'admin'::public.organization_role,'manager'::public.organization_role]));
